       border: 1px solid var(--success-border);
       border-radius: 12px;
       background: var(--success-bg);
       color: #c9ffd0;
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Terms Confirmation</h1>
     <p>Please confirm your consent before submitting the form.</p>

     <form id="consent-form">
       <div class="form-field">
         <div class="checkbox-row">
           <input id="terms" name="terms" type="checkbox" required>
           <label for="terms">I agree to the terms of use.</label>
         </div>
         <p class="helper-text">Required to continue.</p>
       </div>

       <button type="submit">Submit</button>
       <div id="status" class="status" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById("consent-form");
     const status = document.getElementById("status");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       if (!form.reportValidity()) {
         status.textContent = "";
         status.className = "status";
         return;
       }

       status.textContent = "Consent recorded successfully.";
       status.className = "status success";
     });
   </script>
 </body>
